// Keep the original operation records as the content source. Only the exported
// tree below determines public navigation. This also preserves every old URL.
const legacyNodes = new Map();
const legacyPaths = new Map();
function indexLegacy(node, parent = '') {
  const path = parent + '/' + node.id;
  legacyNodes.set(node.id, node);
  legacyPaths.set(path, node.id);
  (node.children || []).forEach(child => indexLegacy(child, path));
}
indexLegacy(legacyProductionTree);
const original = (id, changes = {}) => ({ ...legacyNodes.get(id), ...changes });
const option = (baseId, id, title, intro, result, brief, notes, properties) => ({
  ...original(baseId), id, title, intro, result, brief,
  notes: notes || original(baseId).notes,
  ...(properties ? { properties } : {}),
});
const process = (id, title, intro, image, children) => branch(id, title, intro, image, children);

const bevelWidths = [5, 10, 15, 20, 25, 30, 35, 40];
function bevelGeometry(curved) {
  const geometry = curved ? 'Криволинейный' : 'Прямолинейный';
  const type = curved ? 'curved' : 'straight';
  const baseId = 'production-bevel-' + type;
  const notes = [
    'Ширина — выбранный параметр задания. Толщину стекла, остаточный торец и геометрию фацета увязывают по чертежу.',
    curved ? 'Для фигурного контура проверяют внутренние радиусы и переходы между участками.' : 'В панно ширину и направление фацета увязывают со стыками соседних элементов.',
  ];
  const widths = bevelWidths.map(width => option(baseId,
    `production-bevel-${type}-${width}`, `${geometry} фацет ${width} мм`,
    `Полированная скошенная грань шириной ${width} мм ${curved ? 'по фигурному контуру' : 'вдоль прямых сторон'}.`,
    `Стекло или зеркало с ${curved ? 'криволинейным' : 'прямолинейным'} фацетом выбранной ширины ${width} мм по согласованному чертежу.`,
    ['Размеры и толщина детали', curved ? 'Чертёж контура с радиусами' : 'Стороны для фацетирования', 'Лицевая сторона и остаточный торец', 'Количество и раскладка элементов'],
    notes, { bevelWidth: width + ' мм', bevelGeometry: geometry }));
  widths.push(original(baseId, {
    title: `${geometry} фацет — индивидуальная ширина`,
    intro: 'Укажите точную ширину в миллиметрах для выбранных сторон или участков контура.',
    result: `Стекло или зеркало с ${curved ? 'криволинейным' : 'прямолинейным'} фацетом по индивидуально заданной ширине.`,
    brief: ['Точная ширина фацета в мм', 'Размеры, толщина и материал', 'Обрабатываемые стороны или чертёж контура', 'Лицевая сторона и схема стыков'],
    notes, properties: { bevelWidth: 'Индивидуальная', bevelGeometry: geometry },
  }));
  return process('production-bevel-' + type + '-widths', geometry + ' фацет',
    'Выберите ширину скоса или задайте точное значение для своего чертежа.', 'service-bevel', widths);
}

