// Old material-family service IDs expand to the actual standalone processes.
export const productionServiceGroups = {
  'cutting-machining': ['production-cutting','production-drilling','production-countersinking','production-cutouts','production-grooves','production-cnc','production-rounding'],
  'edge-finishing': ['production-arrising','production-grinding','production-polishing','production-bevel','production-mitre'],
  'thermal-forming': ['production-tempering','production-bending','production-bending-tempering'],
  lamination: ['production-lamination'],
  'surface-decoration': ['production-sandblast','production-mirror-light','production-mechanical-engraving','production-laser-engraving','production-painting','production-enamelling','production-uv-printing','production-ceramic-printing','production-screen-printing','production-films'],
  bonding: ['production-bonding'],
};
const materialOverrides = {
  'production-cutting-laminated': ['laminated'],
  'production-edge-ground-laminated': ['laminated'],
  'production-edge-polished-laminated': ['laminated'],
  'production-film-mirror-backing': ['mirrors','films'],
};
const currentPathsById = new Map();
function indexCurrent(node, parent = '') {
  const path = parent + '/' + node.id;
  if (currentPathsById.has(node.id)) throw new Error('Duplicate production ID: ' + node.id);
  if (materialOverrides[node.id]) node.materialIds = materialOverrides[node.id];
  currentPathsById.set(node.id, path);
  (node.children || []).forEach(child => indexCurrent(child, path));
}
indexCurrent(productionTree);
const oldAggregates = new Set(Object.keys(productionServiceGroups));
export const productionPathAliases = Object.fromEntries([...legacyPaths].map(([oldPath,id]) => [
  oldPath, oldAggregates.has(id) ? '/production' : currentPathsById.get(id) || '/production',
]));

export default productionTree;

// Distinct illustrative views for visibly different edge and hole operations.
const processImageKeys = {
 'production-countersinking':'service-countersink',
 'production-grooves':'service-groove',
 'production-grinding':'service-grinding',
 'production-mitre':'service-mitre',
};
for (const node of productionTree.children) {
 const key=processImageKeys[node.id];
 if(key){const apply=n=>{n.image=key;for(const child of n.children||[])apply(child);};apply(node);}
}
